package FlashlightDesign {
    doc /* A hand-held flashlight, as a small example system. */

    private import ScalarValues::*;
    private import ISQ::*;
    private import SI::*;
    private import FlashlightBehaviour::FlashlightModes;

    // --- What flows between the parts, and where it connects ------------
    item def ElectricPower {
        doc /* Electrical energy, from the battery to the light. */
    }

    port def PowerPort {
        doc /* A connection point where power goes out. A part that takes power in
             * has ~PowerPort, the mirror image: what goes out of one comes into the other. */
        out item power : ElectricPower;
    }

    interface def Wire {
        doc /* A wire between two parts: power flows from the supply to the load. */
        end supply : PowerPort;
        end load : ~PowerPort;
        flow of ElectricPower from supply.power to load.power;
    }

    // --- The kinds of part, like datasheets ------------------------------
    part def Battery {
        doc /* Two AA cells in a holder. */
        attribute mass :> ISQ::mass = 48 [g];
        port powerOut : PowerPort;
    }

    part def Switch {
        doc /* A push button that turns the light on and off. */
        attribute mass :> ISQ::mass = 4 [g];
        port powerIn : ~PowerPort;
        port powerOut : PowerPort;
    }

    part def Led {
        doc /* The light source and its driver board. */
        attribute mass :> ISQ::mass = 6 [g];
        port powerIn : ~PowerPort;
    }

    part def Housing {
        doc /* The aluminium body, lens and end cap. */
        attribute mass :> ISQ::mass = 72 [g];
    }

    part def Flashlight {
        doc /* A hand-held light. */
        attribute mass :> ISQ::mass;
        attribute runTime :> ISQ::duration {
            doc /* How long it stays lit on new batteries, from the battery's capacity
                 * and the LED's current. */
        }
        exhibit state modes : FlashlightModes;
    }

    // --- The design: this flashlight, made of those parts -----------------
    part flashlight : Flashlight {
        part battery : Battery;
        part switch : Switch;
        part led : Led;
        part housing : Housing;

        interface batteryToSwitch : Wire connect battery.powerOut to switch.powerIn;
        interface switchToLed : Wire connect switch.powerOut to led.powerIn;

        // A mass roll-up: like a spreadsheet formula, kept in the model.
        attribute :>> mass = battery.mass + switch.mass + led.mass + housing.mass;
        attribute :>> runTime = 3 [h];
    }
}

package FlashlightRequirements {
    doc /* What the flashlight must do. Each requirement's limit is written as a
         * constraint, so the app checks it against the design's values. */

    private import ISQ::*;
    private import SI::*;
    private import FlashlightDesign::Flashlight;
    private import FlashlightDesign::flashlight;

    requirement def FlashlightRequirement {
        doc /* A requirement on the flashlight. */
        subject light : Flashlight;
    }

    requirement <'REQ-001'> 'Maximum mass' : FlashlightRequirement {
        doc /* The flashlight, with its batteries, shall weigh no more than 150 g. */
        require constraint { light.mass <= 150 [g] }
    }

    requirement <'REQ-002'> 'Run time' : FlashlightRequirement {
        doc /* On new batteries, the flashlight shall stay lit for at least 2 hours. */
        require constraint { light.runTime >= 2 [h] }
    }

    // --- What meets each requirement --------------------------------------
    satisfy 'Maximum mass' by flashlight;
    satisfy 'Run time' by flashlight;
}

package FlashlightBehaviour {
    doc /* What the flashlight is doing, as a state machine. It is always in one
         * state; a transition says which state it leaves (first), what makes it
         * move (accept) and where it goes (then). Run it from Simulations. */

    private import ScalarValues::*;

    item def ButtonPress {
        doc /* Someone pressed the button. */
    }

    state def FlashlightModes {
        doc /* Off, on, and on with a low battery. */
        attribute charge : Real = 1.0 {
            doc /* Battery charge left: 0 is empty, 1 is full. */
        }
        attribute lowLevel : Real = 0.15 {
            doc /* Below this charge, the light dims to last longer. */
        }

        entry; then off;

        state off {
            doc /* Dark. */
        }
        state on {
            doc /* Lit at full brightness. Each hour lit uses 30 % of the battery. */
        }
        state lowBattery {
            doc /* Still lit, but dimmed to save the battery. */
        }

        transition switchOn first off accept ButtonPress then on;
        transition switchOff first on accept ButtonPress then off;
        transition drain first on accept after 1 [SI::h] do assign charge := charge - 0.3 then on;
        transition batteryLow first on accept when charge < lowLevel then lowBattery;
        transition switchOffLow first lowBattery accept ButtonPress then off;
    }
}

package FlashlightVerification {
    doc /* How we will show the flashlight meets its requirements. */

    private import VerificationCases::*;
    private import FlashlightRequirements::*;
    private import FlashlightDesign::flashlight;

    verification <'VC-001'> weighTest {
        doc /* Weigh three flashlights with batteries fitted. Passes at 150 g or less. */
        subject unit :> flashlight;
        objective { verify 'Maximum mass'; }
        @VerificationMethod { kind = VerificationMethodKind::test; }
    }

    verification <'VC-002'> runTimeTest {
        doc /* Switch on with new batteries and time how long it stays lit. Passes at 2 hours or more. */
        subject unit :> flashlight;
        objective { verify 'Run time'; }
        @VerificationMethod { kind = VerificationMethodKind::test; }
    }
}

package FlashlightViews {
    doc /* Saved views: diagrams and tables that are part of the model. */

    private import StandardViewDefinitions::*;
    private import Views::asTreeDiagram;
    private import ModelViews::*;

    view partsTree : GeneralView {
        doc /* The flashlight and what it is made of. */
        expose FlashlightDesign::flashlight::**;
        render asTreeDiagram;
    }

    view connections : InterconnectionView {
        doc /* The parts inside the flashlight, with their ports and wires. */
        expose FlashlightDesign::flashlight::*;
    }

    view massBudget : MassBudget {
        doc /* The flashlight's mass, added up over its parts, against its limit. */
        expose FlashlightDesign::flashlight::**;
    }

    view requirements : RequirementsTable {
        doc /* The requirements, what meets them and whether the design passes. */
        expose FlashlightRequirements::*;
    }

    view designChecks : ConstraintChecks {
        doc /* Each limit, checked against the design's values. */
    }

    view modes : StateTransitionView {
        doc /* Off, on and low battery, and what switches between them. */
        expose FlashlightBehaviour::FlashlightModes;
    }
}

package Reporting {
    doc
    /*
     * The table-rendering convention for SysML v2 views: attach
     * @TableRendering to a view def to say which rows and columns its table
     * has. Documented in docs/table-rendering.md of Fairtide.
     */

    private import ScalarValues::*;

    metadata def TableRendering {
        attribute rows : String;
        attribute columns : String[0..1];
        attribute sortBy : String[0..1];
        attribute pivot : String[0..1];
        attribute where : String[0..1];
        attribute cellLevel : String[0..1];
    }

    // --- Domain-neutral views usable in any model ---------------------

    view def PortTable {
        doc /* Every port with its owner, type, and direction. */
        @TableRendering {
            rows = "kind:port";
            columns = "element; parent; type; direction";
            sortBy = "parent";
        }
    }

    view def AllocationMatrix {
        doc /* Allocation relationships, source to target. */
        @TableRendering {
            rows = "relation:allocation";
            columns = "source; target";
            sortBy = "source";
        }
    }

    view def RequirementsTraceMatrix {
        doc
        /*
         * One row per requirement with what satisfies it and what verifies
         * it — the requirements traceability matrix. An empty cell is a gap.
         */
        @TableRendering {
            rows = "trace";
            columns = "requirement; id; satisfiedBy; verifiedBy";
            sortBy = "requirement";
        }
    }

    view def ModelStats {
        doc /* Element counts by kind: the model at a glance. */
        @TableRendering {
            rows = "kindcounts";
            columns = "kind; definitions; usages";
        }
    }

    view def ConnectionTable {
        doc /* Every connection, source to target. */
        @TableRendering {
            rows = "relation:connection";
            columns = "source; target";
            sortBy = "source";
        }
    }
}

library package ModelViews {
    doc
    /*
     * Standard tables over any SysML v2 model: requirements, coverage gaps,
     * traceability, interfaces, the bill of materials, budgets (mass and
     * power), constraint checks and trade studies.
     *
     * Each table is an ordinary `view def` whose @TableRendering (from the
     * Reporting library) says which rows to collect and which columns to
     * show, so a tool renders it without knowing anything about it. To
     * look at only part of a model, type a view usage by one of these defs
     * and narrow it with `expose`:
     *
     *   view safetyRequirements : RequirementsTable {
     *       expose SafetyRequirements::*;
     *   }
     *
     * `expose P::*` keeps the members of P, `expose P::**` everything
     * nested in P, and `filter @SysML::PartUsage` keeps one kind of
     * element. A view without `expose` shows the whole model.
     *
     * Reports (SpecificationDocument, InterfaceControlDocument) are views
     * too: rendered `asDocument`, each subview becomes a chapter, and the
     * report's `expose` decides what the chapters cover.
     */

    private import Reporting::*;

    view def RequirementsTable {
        doc /* Every requirement with its ID, statement, classification, status, trace links and whether the design meets it. */
        @TableRendering {
            rows = "requirements";
            columns = "id; title; text; kind; priority; verificationMethod; status; owner; satisfiedBy; check; verifiedBy";
            sortBy = "id";
        }
    }

    view def RequirementGaps {
        doc /* Requirements that nothing in the design satisfies yet, or that no verification case checks. */
        @TableRendering {
            rows = "requirements";
            columns = "id; title; satisfied; verified; satisfiedBy; verifiedBy; status; owner";
            where = "satisfied == 0 or verified == 0";
            sortBy = "id";
        }
    }

    view def TraceMatrix {
        doc /* Requirements down the side, the design elements that satisfy them across the top. */
        @TableRendering {
            rows = "relation:satisfy";
            pivot = "requirement; by";
            sortBy = "requirement";
        }
    }

    view def VerificationMatrix {
        doc /* Requirements down the side, the verification cases that check them across the top. */
        @TableRendering {
            rows = "relation:verify";
            pivot = "requirement; by";
            sortBy = "requirement";
        }
    }

    view def InterfaceTable {
        doc /* Every port: which part owns it, what flows through it, and what it is connected to. */
        @TableRendering {
            rows = "kind:port";
            columns = "owner; element; type; direction; connectedTo; via";
            sortBy = "owner";
        }
    }

    view def BillOfMaterials {
        doc /* What the system is made of: each part with how many are used, per assembly and in total. */
        @TableRendering {
            rows = "composition";
            columns = "path; type; quantity; extended; description = doc";
            sortBy = "path";
        }
    }

    view def MassBudget {
        doc /* What each part weighs, how many there are, and what each assembly and the whole add up to. */
        @TableRendering {
            rows = "budget:mass";
            columns = "path; type; quantity; each; total; share; limit; margin; check";
        }
    }

    view def PowerBudget {
        doc /* The electrical power each part draws, how many there are, and what each assembly and the whole draw. */
        @TableRendering {
            rows = "budget:powerDraw";
            columns = "path; type; quantity; each; total; share; limit; margin; check";
        }
    }

    view def ConstraintChecks {
        doc
        /*
         * Does the design meet its requirements? Every requirement constraint,
         * evaluated against the values of the design element that satisfies
         * it (`satisfy R by x`), and every `assert constraint`: satisfied,
         * violated, or undecided with the reason. Requirements stated only in
         * words are left out: they have nothing to evaluate.
         */
        @TableRendering {
            rows = "checks";
            columns = "status; id; requirement; by; margin; detail";
            where = "checkable == 1";
            sortBy = "-status";
        }
    }

    view def TradeStudyTable {
        doc
        /*
         * A trade study's alternatives side by side: what each gives on every
         * criterion, its score and its rank, with the alternative the study's
         * objective selects marked. Expose the trade study to show:
         *
         *   view batteryTrade : TradeStudyTable {
         *       expose BatteryTrade::batteryTradeStudy;
         *   }
         */
        @TableRendering {
            rows = "trade";
            columns = "criterion; weight; alternatives";
        }
    }

    // --- Reports: documents to read and send for review ------------------
    // A report is a view rendered `asDocument`: a title page and contents,
    // then a chapter per subview. Names are qualified so this section can
    // be copied into another project's ModelViews as it is.

    metadata def DocumentInfo {
        doc /* Title-page details of a report. Values left out come from the project. */
        attribute title : ScalarValues::String[0..1];
        attribute number : ScalarValues::String[0..1];
        attribute version : ScalarValues::String[0..1];
        attribute status : ScalarValues::String[0..1];
        attribute author : ScalarValues::String[0..1];
    }

    rendering def DocumentRendering :> Views::TextualRendering {
        doc
        /*
         * Renders a view as a document: a title page and contents, then one
         * chapter per subview, in order, each covering what the document's
         * `expose` includes.
         */
    }

    rendering asDocument : DocumentRendering[1] :> Views::renderings;

    view def SpecificationDocument {
        doc
        /*
         * A requirements specification: each requirement with its statement,
         * attributes and rationale, what satisfies and verifies it, then the
         * coverage and the gaps. Expose the requirement packages to include:
         *
         *   view systemSpecification : SpecificationDocument {
         *       @DocumentInfo { title = "System specification"; version = "1.0"; }
         *       expose SystemRequirements::*;
         *   }
         */
        view requirementsChapter : RequirementsTable {
            doc /* The requirements, by package, each with its attributes and trace. */
        }
        view traceabilityChapter : TraceMatrix {
            doc /* What satisfies and what verifies each requirement, at a glance. */
        }
        view coverageChapter : RequirementsTraceMatrix {
            doc /* How many requirements are satisfied and verified. */
        }
        view gapsChapter : RequirementGaps {
            doc /* Requirements not yet satisfied or not yet verified. */
        }
        render asDocument;
    }

    view def InterfaceControlDocument {
        doc
        /*
         * An interface control document: how the parts in scope connect, the
         * interfaces and ports they connect through, and the items that flow.
         * Expose the parts and the interface packages to include:
         *
         *   view droneIcd : InterfaceControlDocument {
         *       expose DroneArchitecture::drone::*;
         *       expose DroneInterfaces::*;
         *   }
         */
        view interconnectionChapter : StandardViewDefinitions::InterconnectionView {
            doc /* The parts and the connections between them. */
        }
        view connectionsChapter : ConnectionTable {
            doc /* Every connection: which ports it joins and through which interface. */
        }
        view interfacesChapter : StandardViewDefinitions::GeneralView {
            doc /* The interface definitions: their ends and what flows between them. */
            filter @SysML::InterfaceDefinition;
        }
        view portsChapter : StandardViewDefinitions::GeneralView {
            doc /* The port definitions: what goes in and what comes out. */
            filter @SysML::PortDefinition;
        }
        view itemsChapter : StandardViewDefinitions::GeneralView {
            doc /* The items that flow through the ports. */
            filter @SysML::ItemDefinition;
        }
        view portUsageChapter : InterfaceTable {
            doc /* Each part's ports, and what they are connected to. */
        }
        render asDocument;
    }
}
